//! The studio API's client, generated by progenitor, acting as a device as `@conservationtv/studio-sdk` does: every
//! request names its operation's version in `Operation-Version`, and, given a device identity, carries an RFC 9421
//! signature by it.
//!
//! Unlike the TypeScript client, it does not handshake: it speaks only the versions it was generated with, and a
//! server that no longer serves one answers `412`.

mod device;

pub use device::DeviceIdentity;

#[allow(clippy::all, clippy::pedantic, dead_code, unused_imports, mismatched_lifetime_syntaxes)]
mod generated {
    include!(concat!(env!("OUT_DIR"), "/client.rs"));
}
include!(concat!(env!("OUT_DIR"), "/versions.rs"));

pub use generated::*;

use progenitor_client::{ClientHooks, ClientInfo, Error as ClientError, OperationInfo};
use reqwest::header::HeaderValue;

/// What signs each request: a device's identity, or nothing, for operations anyone may call.
#[derive(Clone, Debug, Default)]
pub struct Signer(pub Option<DeviceIdentity>);

/// The version this client speaks of an operation, or `None` for a versionless one.
pub fn operation_version(method: &str) -> Option<u32> {
    OPERATION_VERSIONS.iter().find(|(name, _)| *name == method).map(|(_, version)| *version)
}

impl ClientHooks<Signer> for Client {
    async fn pre<E>(
        &self,
        request: &mut reqwest::Request,
        info: &OperationInfo,
    ) -> Result<(), ClientError<E>> {
        let headers = request.headers_mut();
        // progenitor sends the document's version as `api-version`; the studio API versions each operation instead.
        headers.remove("api-version");
        if let Some(version) = operation_version(info.operation_id) {
            headers.insert("operation-version", HeaderValue::from(version));
        }
        if let Some(identity) = &self.inner().0 {
            identity.sign(request).map_err(|error| ClientError::Custom(error.to_string()))?;
        }
        Ok(())
    }
}

impl Client {
    /// A client for the studio API at `base_url`, signing every request as `identity`.
    pub fn as_device(base_url: &str, identity: DeviceIdentity) -> Self {
        Self::new_with_client(base_url, reqwest::Client::new(), Signer(Some(identity)))
    }
}
